let trans_c_terminator ((kind, body) : mt) : CST.c_terminator =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `SEMI (
            Run.trans_token (Run.matcher_token v)
          )
      | Alt (1, v) ->
          `Pat_1d78758 (
            trans_pat_1d78758 (Run.matcher_token v)
          )
      | Alt (2, v) ->
          `AMP (
            Run.trans_token (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

