            | Alt (0, v) ->
                `COMMA (
                  Run.trans_token (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `COMMACOMMA (
                  Run.trans_token (Run.matcher_token v)
                )
            | Alt (2, v) ->
                `HAT (
                  Run.trans_token (Run.matcher_token v)
                )
            | Alt (3, v) ->
                `HATHAT (
                  Run.trans_token (Run.matcher_token v)
