let trans_simple_expansion ((kind, body) : mt) : CST.simple_expansion =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `DOLLAR_choice_orig_simple_var_name (
            (match v with
            | Seq [v0; v1] ->
                (
                  Run.trans_token (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `Orig_simple_var_name (
                        trans_orig_simple_variable_name (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Choice_STAR (
                        (match v with
                        | Alt (0, v) ->
                            `STAR (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `AT (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (2, v) ->
                            `QMARK (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (3, v) ->
                            `BANG (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (4, v) ->
                            `HASH (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (5, v) ->
                            `DASH (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (6, v) ->
                            `DOLLAR (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (7, v) ->
                            `X__ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                      )
                  | Alt (2, v) ->
                      `BANG (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (3, v) ->
                      `HASH (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
          )
      | Alt (1, v) ->
          `Semg_named_ellips (
            trans_semgrep_named_ellipsis (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let rec trans_arithmetic_binary_expression ((kind, body) : mt) : CST.arithmetic_binary_expression =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Arit_exp_choice_PLUSEQ_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `PLUSEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `DASHEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (2, v) ->
                      `STAREQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (3, v) ->
                      `SLASHEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (4, v) ->
                      `PERCEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (5, v) ->
                      `STARSTAREQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (6, v) ->
                      `LTLTEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (7, v) ->
                      `GTGTEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (8, v) ->
                      `AMPEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (9, v) ->
                      `HATEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (10, v) ->
                      `BAREQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (1, v) ->
          `Arit_exp_choice_EQ_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `EQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `EQTILDE (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (2, v) ->
          `Arit_exp_BARBAR_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  Run.trans_token (Run.matcher_token v1),
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (3, v) ->
          `Arit_exp_AMPAMP_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  Run.trans_token (Run.matcher_token v1),
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (4, v) ->
          `Arit_exp_BAR_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  Run.trans_token (Run.matcher_token v1),
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (5, v) ->
          `Arit_exp_HAT_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  Run.trans_token (Run.matcher_token v1),
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (6, v) ->
          `Arit_exp_AMP_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  Run.trans_token (Run.matcher_token v1),
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (7, v) ->
          `Arit_exp_choice_EQEQ_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `EQEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `BANGEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (8, v) ->
          `Arit_exp_choice_LT_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `LT (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `GT (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (2, v) ->
                      `LTEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (3, v) ->
                      `GTEQ (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (9, v) ->
          `Arit_exp_choice_LTLT_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `LTLT (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `GTGT (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (10, v) ->
          `Arit_exp_choice_PLUS_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `PLUS (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `DASH (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (11, v) ->
          `Arit_exp_choice_STAR_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  (match v1 with
                  | Alt (0, v) ->
                      `STAR (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `SLASH (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | Alt (2, v) ->
                      `PERC (
                        Run.trans_token (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | Alt (12, v) ->
          `Arit_exp_STARSTAR_arit_exp (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  trans_arithmetic_expression (Run.matcher_token v0),
                  Run.trans_token (Run.matcher_token v1),
                  trans_arithmetic_expression (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_arithmetic_expansion ((kind, body) : mt) : CST.arithmetic_expansion =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `DOLLARLPARLPAR_arit_exp_rep_COMMA_arit_exp_RPARRPAR (
            (match v with
            | Seq [v0; v1; v2; v3] ->
                (
                  Run.trans_token (Run.matcher_token v0),
                  trans_arithmetic_expression (Run.matcher_token v1),
                  Run.repeat
                    (fun v ->
                      (match v with
                      | Seq [v0; v1] ->
                          (
                            Run.trans_token (Run.matcher_token v0),
                            trans_arithmetic_expression (Run.matcher_token v1)
                          )
                      | _ -> assert false
                      )
                    )
                    v2
                  ,
                  Run.trans_token (Run.matcher_token v3)
                )
            | _ -> assert false
            )
          )
      | Alt (1, v) ->
          `DOLLARLBRACK_arit_exp_RBRACK (
            (match v with
            | Seq [v0; v1; v2] ->
                (
                  Run.trans_token (Run.matcher_token v0),
                  trans_arithmetic_expression (Run.matcher_token v1),
                  Run.trans_token (Run.matcher_token v2)
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_arithmetic_expression ((kind, body) : mt) : CST.arithmetic_expression =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Arit_lit (
            trans_arithmetic_literal (Run.matcher_token v)
          )
      | Alt (1, v) ->
          `Arit_un_exp (
            trans_arithmetic_unary_expression (Run.matcher_token v)
          )
      | Alt (2, v) ->
          `Arit_tern_exp (
            trans_arithmetic_ternary_expression (Run.matcher_token v)
          )
      | Alt (3, v) ->
          `Arit_bin_exp (
            trans_arithmetic_binary_expression (Run.matcher_token v)
          )
      | Alt (4, v) ->
          `Arit_post_exp (
            trans_arithmetic_postfix_expression (Run.matcher_token v)
          )
      | Alt (5, v) ->
          `Arit_paren_exp (
            trans_arithmetic_parenthesized_expression (Run.matcher_token v)
          )
      | Alt (6, v) ->
          `Cmd_subs (
            trans_command_substitution (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_arithmetic_literal ((kind, body) : mt) : CST.arithmetic_literal =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `DOTDOTDOT (
            Run.trans_token (Run.matcher_token v)
          )
      | Alt (1, v) ->
          `Semg_deep_exp (
            trans_semgrep_deep_expression (Run.matcher_token v)
          )
      | Alt (2, v) ->
          `Num (
            trans_number (Run.matcher_token v)
          )
      | Alt (3, v) ->
          `Subs (
            trans_subscript (Run.matcher_token v)
          )
      | Alt (4, v) ->
          `Simple_expa (
            trans_simple_expansion (Run.matcher_token v)
          )
      | Alt (5, v) ->
          `Expa (
            trans_expansion (Run.matcher_token v)
          )
      | Alt (6, v) ->
          `Orig_simple_var_name (
            trans_orig_simple_variable_name (Run.matcher_token v)
          )
      | Alt (7, v) ->
          `Var_name (
            trans_variable_name (Run.matcher_token v)
          )
      | Alt (8, v) ->
          `Str (
            trans_string_ (Run.matcher_token v)
          )
      | Alt (9, v) ->
          `Raw_str (
            trans_raw_string (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_arithmetic_parenthesized_expression ((kind, body) : mt) : CST.arithmetic_parenthesized_expression =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            Run.trans_token (Run.matcher_token v0),
            trans_arithmetic_expression (Run.matcher_token v1),
            Run.trans_token (Run.matcher_token v2)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_arithmetic_postfix_expression ((kind, body) : mt) : CST.arithmetic_postfix_expression =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1] ->
          (
            trans_arithmetic_expression (Run.matcher_token v0),
            (match v1 with
            | Alt (0, v) ->
                `PLUSPLUS (
                  Run.trans_token (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `DASHDASH (
                  Run.trans_token (Run.matcher_token v)
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_arithmetic_ternary_expression ((kind, body) : mt) : CST.arithmetic_ternary_expression =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3; v4] ->
          (
            trans_arithmetic_expression (Run.matcher_token v0),
            Run.trans_token (Run.matcher_token v1),
            trans_arithmetic_expression (Run.matcher_token v2),
            Run.trans_token (Run.matcher_token v3),
            trans_arithmetic_expression (Run.matcher_token v4)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_arithmetic_unary_expression ((kind, body) : mt) : CST.arithmetic_unary_expression =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Choice_tok_prec_p1_plusps_arit_exp (
            (match v with
            | Seq [v0; v1] ->
                (
                  (match v0 with
                  | Alt (0, v) ->
                      `Tok_prec_p1_plusps (
                        trans_tok_prec_p1_plusplus (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Tok_prec_p1_dash (
                        trans_tok_prec_p1_dashdash (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v1)
                )
            | _ -> assert false
            )
          )
      | Alt (1, v) ->
          `Choice_tok_prec_p1_dash_arit_exp (
            (match v with
            | Seq [v0; v1] ->
                (
                  (match v0 with
                  | Alt (0, v) ->
                      `Tok_prec_p1_dash (
                        trans_tok_prec_p1_dash (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Tok_prec_p1_plus (
                        trans_tok_prec_p1_plus (Run.matcher_token v)
                      )
                  | Alt (2, v) ->
                      `Tok_prec_p1_tilde (
                        trans_tok_prec_p1_tilde (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                  ,
                  trans_arithmetic_expression (Run.matcher_token v1)
                )
            | _ -> assert false
            )
          )
      | Alt (2, v) ->
          `BANG_arit_exp (
            (match v with
            | Seq [v0; v1] ->
                (
                  Run.trans_token (Run.matcher_token v0),
                  trans_arithmetic_expression (Run.matcher_token v1)
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_array_ ((kind, body) : mt) : CST.array_ =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            Run.trans_token (Run.matcher_token v0),
            Run.repeat
              (fun v ->
                (match v with
                | Alt (0, v) ->
                    `Conc (
                      trans_concatenation (Run.matcher_token v)
                    )
                | Alt (1, v) ->
                    `Choice_semg_deep_exp (
                      (match v with
                      | Alt (0, v) ->
                          `Semg_deep_exp (
                            trans_semgrep_deep_expression (Run.matcher_token v)
                          )
                      | Alt (1, v) ->
                          `DOTDOTDOT (
                            Run.trans_token (Run.matcher_token v)
                          )
                      | Alt (2, v) ->
                          `Choice_word (
                            (match v with
                            | Alt (0, v) ->
                                `Word (
                                  trans_word (Run.matcher_token v)
                                )
                            | Alt (1, v) ->
                                `Test_op (
                                  trans_test_operator (Run.matcher_token v)
                                )
                            | Alt (2, v) ->
                                `Str (
                                  trans_string_ (Run.matcher_token v)
                                )
                            | Alt (3, v) ->
                                `Raw_str (
                                  trans_raw_string (Run.matcher_token v)
                                )
                            | Alt (4, v) ->
                                `Tran_str (
                                  trans_translated_string (Run.matcher_token v)
                                )
                            | Alt (5, v) ->
                                `Ansi_c_str (
                                  trans_ansi_c_string (Run.matcher_token v)
                                )
                            | Alt (6, v) ->
                                `Num (
                                  trans_number (Run.matcher_token v)
                                )
                            | Alt (7, v) ->
                                `Expa (
                                  trans_expansion (Run.matcher_token v)
                                )
                            | Alt (8, v) ->
                                `Simple_expa (
                                  trans_simple_expansion (Run.matcher_token v)
                                )
                            | Alt (9, v) ->
                                `Cmd_subs (
                                  trans_command_substitution (Run.matcher_token v)
                                )
                            | Alt (10, v) ->
                                `Proc_subs (
                                  trans_process_substitution (Run.matcher_token v)
                                )
                            | Alt (11, v) ->
                                `Arit_expa (
                                  trans_arithmetic_expansion (Run.matcher_token v)
                                )
                            | Alt (12, v) ->
                                `Brace_exp (
                                  trans_brace_expression (Run.matcher_token v)
                                )
                            | _ -> assert false
                            )
                          )
                      | _ -> assert false
                      )
                    )
                | Alt (2, v) ->
                    `Rep1_spec_char (
                      Run.repeat1
                        (fun v -> trans_special_character (Run.matcher_token v))
                        v
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            Run.trans_token (Run.matcher_token v2)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_binary_expression ((kind, body) : mt) : CST.binary_expression =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Choice_exp_choice_PLUSEQ_exp (
            (match v with
            | Alt (0, v) ->
                `Exp_choice_PLUSEQ_exp (
                  (match v with
                  | Seq [v0; v1; v2] ->
                      (
                        trans_expression (Run.matcher_token v0),
                        (match v1 with
                        | Alt (0, v) ->
                            `PLUSEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `DASHEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (2, v) ->
                            `STAREQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (3, v) ->
                            `SLASHEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (4, v) ->
                            `PERCEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (5, v) ->
                            `STARSTAREQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (6, v) ->
                            `LTLTEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (7, v) ->
                            `GTGTEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (8, v) ->
                            `AMPEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (9, v) ->
                            `HATEQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (10, v) ->
                            `BAREQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                        ,
                        trans_expression (Run.matcher_token v2)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Exp_choice_EQ_exp (
                  (match v with
                  | Seq [v0; v1; v2] ->
                      (
                        trans_expression (Run.matcher_token v0),
                        (match v1 with
                        | Alt (0, v) ->
                            `EQ (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `EQTILDE (
                              Run.trans_token (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                        ,
                        trans_expression (Run.matcher_token v2)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (2, v) ->
                `Exp_BARBAR_exp (
                  (match v with
                  | Seq [v0; v1; v2] ->
                      (
                        trans_expression (Run.matcher_token v0),
                        Run.trans_token (Run.matcher_token v1),
                        trans_expression (Run.matcher_token v2)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (3, v) ->
                `Exp_AMPAMP_exp (
                  (match v with
                  | Seq [v0; v1; v2] ->
                      (
                        trans_expression (Run.matcher_token v0),
                        Run.trans_token (Run.matcher_token v1),
                        trans_expression (Run.matcher_token v2)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (4, v) ->
                `Exp_BAR_exp (
                  (match v with
