      | Seq [v0; v1; v2; v3] ->
          (
            Run.trans_token (Run.matcher_token v0),
            Run.repeat
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      (match v0 with
                      | Alt (0, v) ->
                          `Opt_DOLLAR_str_content (
                            (match v with
                            | Seq [v0; v1] ->
                                (
                                  Run.opt
                                    (fun v -> Run.trans_token (Run.matcher_token v))
                                    v0
                                  ,
                                  trans_string_content (Run.matcher_token v1)
                                )
                            | _ -> assert false
                            )
                          )
                      | Alt (1, v) ->
                          `Expa (
                            trans_expansion (Run.matcher_token v)
                          )
                      | Alt (2, v) ->
                          `Simple_expa (
                            trans_simple_expansion (Run.matcher_token v)
                          )
                      | Alt (3, v) ->
                          `Cmd_subs (
                            trans_command_substitution (Run.matcher_token v)
                          )
                      | Alt (4, v) ->
                          `Arit_expa (
                            trans_arithmetic_expansion (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                      ,
                      Run.opt
                        (fun v -> trans_concat (Run.matcher_token v))
                        v1
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            Run.opt
              (fun v -> Run.trans_token (Run.matcher_token v))
              v2
            ,
            Run.trans_token (Run.matcher_token v3)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

